arguments.command:
cd /workspace && cat > tmp/fuzz2.py <<'EOF'
import json, sys, random, time
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace')
import gen
from verify import verify
from goldrun import run

mode=sys.argv[1]; lo=int(sys.argv[2]); hi=int(sys.argv[3])
fails=0
for seed in range(lo,hi):
    rng=random.Random(seed*7919+hash(mode)%1000)
    if mode=="narrow": kw=dict(max_routes=7,max_tx=3,max_bursts=4,narrow=True)
    elif mode=="wide": kw=dict(max_routes=7,max_tx=2,max_bursts=3,narrow=False)
    elif mode=="medium": kw=dict(max_routes=10,max_tx=3,max_bursts=4,narrow=False)
    elif mode=="big": kw=dict(max_routes=14,max_tx=4,max_bursts=5,narrow=True)
    count=rng.randint(0,3)
    req=gen.make_request(seed, count=count, **kw)
    payload=json.dumps(req).encode()
    open('/workspace/tmp/last_%s.json'%mode,'wb').write(payload)
    try:
        out=run(payload)
    except SystemExit as e:
        print("seed",seed,"CHILD FAIL",e); fails+=1; continue
    if "error" in out:
        print("seed",seed,"unexpected invalid"); fails+=1; continue
    try:
        verify(req,out,random.Random(seed))
    except AssertionError as e:
        print("seed",seed,"VERIFY FAIL",str(e)[:300]); fails+=1
    except Exception as e:
        print("seed",seed,"VERIFY ERROR",type(e).__name__,repr(e)[:300]); fails+=1
print(mode,"done, fails =",fails)
EOF
nohup bash tmp/fuzzrun.sh x >/dev/null 2>&1; for m in narrow wide medium big; do (python3 tmp/fuzz2.py $m 0 150 > /workspace/tmp/f_$m.log 2>&1 &) ; done; sleep 100; tail -2 /workspace/tmp/f_*.log
